# frozen_string_literal: true

# Registry of layout templates for page creation.
#
# Each template defines layout rules (field widths, sections, injected elements)
# that get applied to any entity's auto-populated fields based on html_type matching.
#
# Templates also include `preview_rows` — a mini-form blueprint rendered as
# an intuitive thumbnail on the template selection card.
#
# Preview row element types:
#   :section  — section header label
#   :input    — text/email/password input
#   :textarea — multiline text area
#   :select   — dropdown select
#   :checkbox — checkbox / toggle
#   :radio    — radio button group
#   :date     — date picker
#   :number   — numeric input
#   :rating   — star rating
#   :file     — file upload zone
#   :divider  — horizontal divider line
#   :spacer   — vertical spacing
#
# Each element: { type:, width: "full"|"half"|"third", label: "..." }
#
# Template files live under app/services/page_layout_templates/templates/<category>/<key>.rb
# and are auto-discovered by PageLayoutTemplates::Registry.
#
