  CATEGORY_ORDER = (CATEGORIES.keys - ["all"]).freeze

  class << self
    def all              = Registry.all
    def find(key)        = Registry.find(key)
    def keys             = Registry.keys
    def by_category      = Registry.by_category
    def for_category(cat) = Registry.for_category(cat)
    def category_counts  = Registry.category_counts
    def categories       = CATEGORIES
    def category_groups  = CATEGORY_GROUPS

    def category_label(key)
      fallback = CATEGORIES.dig(key.to_s, :label).to_s
      fallback = key.to_s if fallback.empty?
      I18n.t("layout_catalog.categories.#{key}", default: fallback)
    end

    def category_group_label(group)
      I18n.t("layout_catalog.groups.#{group[:key]}", default: group[:label].to_s)
    end

    # Returns templates filtered by a customer's industry.
    # Falls back to all templates if no mappings exist for the industry.
    def for_industry(industry)
      return all if industry.blank?

      allowed_keys = IndustryTemplateMapping.template_keys_for(industry)
      return all if allowed_keys.empty?

      allowed_set = allowed_keys.to_set
      all.select { |t| allowed_set.include?(t[:key]) }
    end

    # Returns category counts for an industry-filtered template set.
    def category_counts_for_industry(industry)
      templates = for_industry(industry)
      counts = templates.group_by { |t| t[:category] }.transform_values(&:size)
      counts["all"] = templates.size
      counts
    end
  end
end
